import random
import string
from typing import List

# Data type: URL path tail
# The fuzzers prepend a fixed base like "http://example.com/" or "https://localhost/"
# Then append our generated tail. We should generate valid URL path/query/fragment tails
# that exercise different code paths while remaining valid and under 128 chars (stub trims).

SAFE_PCHAR = string.ascii_letters + string.digits + "-._~"
SUBDELIMS = "!$&'()*+,;="
PCT_HEX = string.hexdigits.lower()

def _pct_encode_byte(b: int) -> str:
    return "%" + format(b, "02X")

def _random_pct_encoded(rng: random.Random, count: int) -> str:
    # Generate count random percent-encoded bytes (including reserved examples)
    return ''.join(_pct_encode_byte(rng.randrange(0, 256)) for _ in range(count))

def _random_matrix_params(rng: random.Random) -> str:
    # ;param=value pairs
    pairs = []
    for _ in range(rng.randint(1, 3)):
        name = _token(rng, rng.randint(1, 8))
        val = _token(rng, rng.randint(0, 6))
        pairs.append(f";{name}={val}")
    return ''.join(pairs)

def _token(rng: random.Random, n: int) -> str:
    alphabet = SAFE_PCHAR + SUBDELIMS
    return ''.join(rng.choice(alphabet) for _ in range(n))

def _segment(rng: random.Random, with_pct: bool = True) -> str:
    # Generate a single path segment
    parts: List[str] = []
    # Mix of safe chars, subdelims, and optional pct-encoded bytes
    length = rng.randint(0, 20)
    for _ in range(length):
        choice = rng.random()
        if with_pct and choice < 0.15:
            parts.append(_pct_encode_byte(rng.randrange(0, 256)))
        elif choice < 0.7:
            parts.append(rng.choice(SAFE_PCHAR))
        else:
            parts.append(rng.choice(SUBDELIMS))
    # Optionally add matrix parameters
    if rng.random() < 0.2:
        parts.append(_random_matrix_params(rng))
    return ''.join(parts)

def _query(rng: random.Random) -> str:
    # Build query with key=value pairs and arrays
    pairs = []
    n = rng.randint(1, 5)
    for _ in range(n):
        key = _token(rng, rng.randint(1, 8))
        # sometimes key[]= or nested key[a]
        if rng.random() < 0.2:
            key += "[]"
        elif rng.random() < 0.2:
            key += f"[{_token(rng, rng.randint(1,3))}]"
        if rng.random() < 0.15:
            # value omitted
            pairs.append(key)
            continue
        if rng.random() < 0.2:
            # percent-encoded blob
            val = _random_pct_encoded(rng, rng.randint(1, 8))
        else:
            val = _token(rng, rng.randint(0, 10))
        # include reserved separators inside values sometimes
        if rng.random() < 0.25:
            val += rng.choice(["/", ":", "@", ","])  # still allowed in query
        pairs.append(f"{key}={val}")
    sep = rng.choice(["&", ";"])  # both separators are commonly accepted
    return "?" + sep.join(pairs)

def _fragment(rng: random.Random) -> str:
    frag = []
    for _ in range(rng.randint(0, 20)):
        if rng.random() < 0.2:
            frag.append(_pct_encode_byte(rng.randrange(0, 256)))
        else:
            frag.append(rng.choice(SAFE_PCHAR + SUBDELIMS + "/:@"))
    return "#" + ''.join(frag)

def _build_tail(rng: random.Random) -> str:
    # Choose a pattern
    pattern = rng.randrange(0, 8)
    segments: List[str] = []

    if pattern == 0:
        # simple path
        segments = [_segment(rng) for _ in range(rng.randint(0, 4))]
    elif pattern == 1:
        # deep path with empty segments to test // and trailing /
        depth = rng.randint(3, 8)
        for i in range(depth):
            seg = _segment(rng)
            if rng.random() < 0.2:
                seg = ''  # produce //
            segments.append(seg)
        if rng.random() < 0.5:
            segments.append('')  # ensure trailing slash
    elif pattern == 2:
        # path parameters and extensions
        base = _segment(rng)
        ext = rng.choice(["html", "js", "css", "json", "png", "svg", "txt"]) if rng.random() < 0.8 else _token(rng, 3)
        segments = [f"{base}.{ext}" + (_random_matrix_params(rng) if rng.random() < 0.5 else '')]
    elif pattern == 3:
        # semicolon params on multiple segments
        segments = []
        for _ in range(rng.randint(1, 4)):
            segments.append(_segment(rng) + _random_matrix_params(rng))
    elif pattern == 4:
        # reserved characters stress
        seg = ''.join(rng.choice(SAFE_PCHAR + SUBDELIMS + ":@$") for _ in range(rng.randint(1, 20)))
        segments = [seg]
    elif pattern == 5:
        # percent-encoded heavy
        segs = []
        for _ in range(rng.randint(1, 4)):
            segs.append(_random_pct_encoded(rng, rng.randint(1, 6)))
        segments = segs
    elif pattern == 6:
        # unicode via percent-encoding of UTF-8 bytes for non-ASCII
        word = ''.join(chr(rng.randint(0x00A1, 0x07FF)) for _ in range(rng.randint(3, 8)))
        utf8 = word.encode('utf-8')
        segments = [''.join(_pct_encode_byte(b) for b in utf8)]
    else:
        # mixed
        segments = []
        for _ in range(rng.randint(1, 5)):
            segments.append(_segment(rng, with_pct=True))

    path = '/'.join(segments)

    # Optionally add query and/or fragment
    if rng.random() < 0.7:
        path += _query(rng)
    if rng.random() < 0.4:
        path += _fragment(rng)

    # Ensure length cap (stubs trim to 128). We keep under 120 to leave headroom.
    if len(path) > 120:
        path = path[:120]
    return path


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Occasionally produce an empty tail to exercise base URL only
    if rng.random() < 0.1:
        return b""
    tail = _build_tail(rng)
    # Return bytes (UTF-8). Ensure total size <= 4096 (ours is <= 120).
    return tail.encode('utf-8')
